// Approach: Memoization solves each overlapping subproblem once and saves the answer. Fibonacci
//   illustrates the idea.
#include <vector>
using namespace std;
long long fibMemo(int n, vector<long long>& memo) {
    // Memoization saves each Fibonacci answer after its first calculation.
    // Fibonacci's first two values are base cases.
    if (n <= 1) return n;
    // A saved value means this subproblem need not be recomputed.
    if (memo[n] != -1) return memo[n];
    return memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
}
long long fibonacci(int n) {
    // Negative indices do not represent a valid Fibonacci term.
    if (n < 0) return 0;
    vector<long long> memo(n + 1, -1);
    return fibMemo(n, memo);
}

