// Approach: The last move to stair i comes from i-1 or i-2, so add their ways.
long long climbStairs(int n) {
    // There are no ways to climb a negative number of steps.
    if (n < 0) return 0;
    long long twoBefore = 1, oneBefore = 1; // stairs 0 and 1
    for (int stair = 2; stair <= n; ++stair) {
        // The final move is one step from stair-1 or two from stair-2.
        long long current = oneBefore + twoBefore;
        twoBefore = oneBefore;
        oneBefore = current;
    }
    return oneBefore;
}

