// Approach: The cheapest path to stone i ends with a jump from i-1 or i-2.
#include <algorithm>
#include <cstdlib>
#include <vector>
using namespace std;
int frogJump(const vector<int>& height) {
    int n = (int)height.size();
    // With fewer than two stones, no jump cost is required.
    if (n < 2) return 0;
    int twoBefore = 0, oneBefore = abs(height[1] - height[0]);
    // Only the costs for the two previous stones are needed.
    for (int i = 2; i < n; ++i) {
        // Compare a one-stone jump with a two-stone jump.
        int current = min(oneBefore + abs(height[i] - height[i - 1]),
                          twoBefore + abs(height[i] - height[i - 2]));
        twoBefore = oneBefore;
        oneBefore = current;
    }
    return oneBefore;
}

