// Approach: For each stone, try the previous k stones as the final jump.
#include <algorithm>
#include <climits>
#include <cstdlib>
#include <vector>
using namespace std;
int frogJumpK(const vector<int>& height, int k) {
    int n = (int)height.size();
    // No jump is needed for zero or one stone.
    if (n < 2) return 0;
    // A nonpositive jump limit cannot reach a later stone.
    if (k <= 0) return -1;
    vector<int> dp(n, INT_MAX);
    dp[0] = 0;
    // Try each reachable earlier stone as the final jump into i.
    for (int i = 1; i < n; ++i)
        for (int jump = 1; jump <= k && jump <= i; ++jump)
            // This transition pays the jump cost plus the best cost to its source stone.
            dp[i] = min(dp[i], dp[i - jump] +
                               abs(height[i] - height[i - jump]));
    return dp.back();
}

