// Approach: For each day and chosen task, use the best score ending with a different task yesterday.
#include <algorithm>
#include <array>
#include <vector>
using namespace std;
int ninjaTraining(const vector<array<int, 3>>& points) {
    // No days means the maximum training score is zero.
    if (points.empty()) return 0;
    array<int, 3> previous = points[0];
    // Previous[task] is the best score ending with that task yesterday.
    for (int day = 1; day < (int)points.size(); ++day) {
        array<int, 3> current;
        for (int task = 0; task < 3; ++task) {
            int bestPrevious = previous[(task + 1) % 3];
            for (int previousTask = 0; previousTask < 3; ++previousTask) {
                if (previousTask == task) continue; // cannot repeat yesterday's task
                bestPrevious = max(bestPrevious, previous[previousTask]);
            }
            // Choose today's task after the best different task yesterday.
            current[task] = points[day][task] + bestPrevious;
        }
        previous = current;
    }
    return *max_element(previous.begin(), previous.end());
}

s16-grid-unique-paths-dp-on-grids-dp8.code:
// Approach: A cell can be reached from above or left. Update one row in place, left to right.
#include <vector>
using namespace std;
long long uniquePaths(int rows, int cols) {
    // A grid with a nonpositive dimension has no valid path.
    if (rows <= 0 || cols <= 0) return 0;
    vector<long long> ways(cols, 0);
    ways[0] = 1;
    for (int r = 0; r < rows; ++r) {
        for (int c = 1; c < cols; ++c) {
            // Before the update, ways[c] is from above; ways[c-1] is from left.
            ways[c] += ways[c - 1];
        }
    }
    return ways.back();
}

s16-grid-unique-paths-2-dp-9.code:
// Approach: An obstacle has zero ways; otherwise add paths from above and left.
#include <vector>
using namespace std;
long long uniquePathsWithObstacles(const vector<vector<int>>& obstacle) {
    int rows = (int)obstacle.size();
    // An empty grid has no route to the goal.
    if (!rows || obstacle[0].empty()) return 0;
    int cols = (int)obstacle[0].size();
    vector<long long> ways(cols, 0);
    ways[0] = obstacle[0][0] == 0;
    // ways[c] is from above; ways[c-1] is from the left.
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < cols; ++c) {
            // An obstacle destroys every path that would end at this cell.
            // An obstacle blocks all routes ending at this cell.
            if (obstacle[r][c] != 0) ways[c] = 0;
            // Otherwise, add routes from the left when a left cell exists.
            else if (c > 0) ways[c] += ways[c - 1];
        }
    return ways.back();
}

s16-minimum-path-sum-in-grid-dp-10.code:
// Approach: Each cell adds its value to the smaller path sum from above or left.
#include <algorithm>
#include <climits>
#include <vector>
using namespace std;
long long minPathSum(const vector<vector<int>>& grid) {
    int rows = (int)grid.size();
    // An empty grid has no path cost.
    if (!rows || grid[0].empty()) return 0;
    int cols = (int)grid[0].size();
    const long long INF = LLONG_MAX / 4;
    vector<long long> dp(cols, INF);
    // dp[c] is the path from above before this cell is updated.
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < cols; ++c) {
            // The start cell has no incoming path; its cost is its own value.
            if (r == 0 && c == 0) dp[c] = grid[r][c];
            else {
                long long bestIncoming = dp[c]; // path from above
                // A path from the left exists only beyond the first column.
                if (c > 0) {
                    // Compare the left route with the route from above.
                    bestIncoming = min(bestIncoming, dp[c - 1]);
                }
                dp[c] = grid[r][c] + bestIncoming;
            }
        }
    return dp.back();
}

s16-minimum-path-sum-in-triangular-grid-.code:
// Approach: Start at the bottom row; each cell adds the smaller cost of its two children.
#include <algorithm>
#include <vector>
using namespace std;
long long minimumTriangleTotal(const vector<vector<int>>& triangle) {
    int n = (int)triangle.size();
    // An empty triangle has no path cost.
    if (!n) return 0;
    vector<long long> dp(triangle.back().begin(), triangle.back().end());
    // Work upward because each row depends on the row directly below.
    for (int row = n - 2; row >= 0; --row)
        for (int col = 0; col <= row; ++col)
            // The two entries below are the only possible next steps.
            dp[col] = triangle[row][col] + min(dp[col], dp[col + 1]);
    return dp[0];
}

s16-minimum-maximum-falling-path-sum-dp-.code:
// Approach: Each cell adds the best of the three reachable cells above it. Take the best in the final
//   row.
#include <algorithm>
#include <vector>
using namespace std;
long long fallingPathSum(const vector<vector<int>>& grid, bool maximize) {
    // Each cell can come from three cells in the row above.
    // There is no falling path in an empty grid.
    if (grid.empty() || grid[0].empty()) return 0;
    int cols = (int)grid[0].size();
    vector<long long> previous(grid[0].begin(), grid[0].end());
    for (int r = 1; r < (int)grid.size(); ++r) {
        vector<long long> current(cols);
        for (int c = 0; c < cols; ++c) {
            long long best = previous[c];
            // Upper-left exists only when c is not the first column.
            if (c > 0) {
                // Choose the larger upper-left value only in maximum mode.
                if (maximize) best = max(best, previous[c - 1]);
                else best = min(best, previous[c - 1]);
            }
            // Upper-right exists only when c is not the last column.
            if (c + 1 < cols) {
                // Choose the larger upper-right value only in maximum mode.
                if (maximize) best = max(best, previous[c + 1]);
                else best = min(best, previous[c + 1]);
            }
            // Add this cell after choosing the best reachable parent.
            current[c] = grid[r][c] + best;
        }
        previous.swap(current);
    }
    // The answer may end in any column of the final row.
    if (maximize) return *max_element(previous.begin(), previous.end());
    return *min_element(previous.begin(), previous.end());
}

s16-3-d-dp-ninja-and-his-friends-dp-13.code:
// Approach: Track both robots' columns in each row. Try all nine pairs of next moves and count a
//   shared cell once.
#include <algorithm>
#include <vector>
using namespace std;
int maximumChocolates(const vector<vector<int>>& grid) {
    // State (c1,c2) records the best total for both players' columns.
    int rows = (int)grid.size();
    // An empty grid has no chocolates to collect.
    if (!rows || grid[0].empty()) return 0;
    int cols = (int)grid[0].size();
    const int NEG = -1000000000;
    vector<vector<int>> next(cols, vector<int>(cols, NEG));
    for (int a = 0; a < cols; ++a)
        for (int b = 0; b < cols; ++b) {
            next[a][b] = grid.back()[a];
            if (a != b) next[a][b] += grid.back()[b]; // shared cell counts once
        }
    for (int row = rows - 2; row >= 0; --row) {
        vector<vector<int>> current(cols, vector<int>(cols, NEG));
        for (int a = 0; a < cols; ++a)
            for (int b = 0; b < cols; ++b)
                for (int da = -1; da <= 1; ++da)
                    for (int db = -1; db <= 1; ++db) {
                        int na = a + da, nb = b + db;
                        // Reject moves that would take either player outside the grid.
                        if (na < 0 || nb < 0 || na >= cols || nb >= cols) continue;
                        int gain = grid[row][a];
                        if (a != b) gain += grid[row][b]; // do not double-count a shared cell
                        // Try every pair of next columns; count a shared cell only once.
                        current[a][b] = max(current[a][b], gain + next[na][nb]);
                    }
        next.swap(current);
    }
    return next[0][cols - 1];
}

s16-subset-sum-equal-to-target-dp-14.code:
// Approach: Update reachable sums backward so each nonnegative value is used at most once.
#include <vector>
using namespace std;
bool subsetSumToTarget(const vector<int>& values, int target) {
    // Nonnegative values cannot sum to a negative target.
    if (target < 0) return false;
    vector<char> possible(target + 1, false);
    possible[0] = true;
    for (int value : values) {
        // This one-dimensional subset DP is defined for nonnegative values.
        if (value < 0) return false; // this DP assumes nonnegative values
        for (int sum = target; sum >= value; --sum)
            possible[sum] = possible[sum] || possible[sum - value];
    }
    return possible[target];
}

s16-partition-equal-subset-sum-dp-15.code:
// Approach: An equal partition exists if total is even and a subset sums to total/2.
#include <numeric>
#include <vector>
using namespace std;
bool canPartition(const vector<int>& values) {
    long long total = accumulate(values.begin(), values.end(), 0LL);
    // An odd total cannot be split equally; negative total is outside this variant.
    if (total < 0 || total % 2) return false;
    int half = (int)(total / 2);
    vector<char> possible(half + 1, false);
    possible[0] = true;
    for (int value : values) {
        // Negative values require a different DP state representation.
        if (value < 0) return false;
        // Descend so this value cannot be chosen twice.
        for (int sum = half; sum >= value; --sum)
            possible[sum] = possible[sum] || possible[sum - value];
    }
    return possible[half];
}

s16-partition-set-into-2-subsets-with-mi.code:
// Approach: Find reachable subset sums and minimize total minus twice the chosen sum.
#include <algorithm>
#include <numeric>
#include <vector>
using namespace std;
int minimumPartitionDifference(const vector<int>& values) {
    int total = accumulate(values.begin(), values.end(), 0);
    // This variant assumes a nonnegative total.
    if (total < 0) return -1;
    vector<char> possible(total + 1, false);
    possible[0] = true;
    for (int value : values) {
        // Negative values would require shifted or map-based DP states.
        if (value < 0) return -1; // nonnegative-values variant
        for (int sum = total; sum >= value; --sum)
            possible[sum] = possible[sum] || possible[sum - value];
    }
    int answer = total;
    for (int sum = 0; sum <= total / 2; ++sum)
        // Only a reachable subset sum can produce a valid partition difference.
        if (possible[sum]) answer = min(answer, total - 2 * sum);
    return answer;
}

s16-count-subsets-with-sum-k-dp-17.code:
// Approach: Count subsets for each sum, updating backward to use each element once. A zero doubles
//   every count.
#include <vector>
using namespace std;
int countSubsetsWithSum(const vector<int>& values, int target) {
    const int MOD = 1000000007;
    // There are no subsets with a negative sum under nonnegative inputs.
    if (target < 0) return 0;
    vector<int> ways(target + 1, 0);
    ways[0] = 1;
    for (int value : values) {
        // Negative values need a different DP formulation.
        if (value < 0) return 0; // nonnegative-values variant
        for (int sum = target; sum >= value; --sum)
            ways[sum] = (ways[sum] + ways[sum - value]) % MOD;
    }
    return ways[target];
}

s16-count-partitions-with-given-differen.code:
// Approach: For total S and difference D, count subsets of sum (S-D)/2. Zeros naturally double the
//   count.
#include <cstdlib>
#include <numeric>
#include <vector>
using namespace std;
int countPartitionsWithDifference(const vector<int>& values, int difference) {
    const int MOD = 1000000007;
    long long total = accumulate(values.begin(), values.end(), 0LL);
    long long remainder = total - llabs((long long)difference);
    // The derived subset target must be a nonnegative integer.
    if (remainder < 0 || remainder % 2) return 0;
    int target = (int)(remainder / 2);
    vector<int> ways(target + 1, 0);
    ways[0] = 1;
    for (int value : values) {
        // This counting DP assumes nonnegative input values.
        if (value < 0) return 0; // nonnegative-values variant
        for (int sum = target; sum >= value; --sum)
            ways[sum] = (ways[sum] + ways[sum - value]) % MOD;
    }
    return ways[target];
}

s16-assign-cookies.code:
// Approach: Sort greed and cookies. Give each child the smallest remaining cookie that satisfies
//   them.
#include <algorithm>
#include <vector>
using namespace std;
int findContentChildren(vector<int> greed, vector<int> cookies) {
    // Match the least demanding child with the smallest sufficient cookie.
    sort(greed.begin(), greed.end());
    sort(cookies.begin(), cookies.end());
    int child = 0, cookie = 0;
    while (child < (int)greed.size() && cookie < (int)cookies.size()) {
        // A cookie satisfies this child only when its size meets the child's greed.
        if (cookies[cookie] >= greed[child]) ++child;
        ++cookie;
    }
    return child;
}

s16-minimum-coins-dp-20.code:
// Approach: Try every coin as the final coin of each amount; coins may be reused.
#include <algorithm>
#include <vector>
using namespace std;
int minimumCoins(const vector<int>& coins, int amount) {
    // A negative amount cannot be formed with positive coins.
    if (amount < 0) return -1;
    const int INF = amount + 1;
    vector<int> dp(amount + 1, INF);
    dp[0] = 0;
    // dp[sum] is the fewest coins needed to make this sum.
    for (int sum = 1; sum <= amount; ++sum)
        for (int coin : coins)
            // Ignore coins that are invalid or larger than the current amount.
            if (coin > 0 && coin <= sum)
                // Take this coin after the best solution for the remaining sum.
                dp[sum] = min(dp[sum], dp[sum - coin] + 1);
    if (dp[amount] == INF) return -1; // no combination makes this amount
    return dp[amount];
}

s16-target-sum-dp-21.code:
// Approach: Choosing negative signs is choosing a subset of sum (total-target)/2. A zero doubles
//   every count.
#include <numeric>
#include <vector>
using namespace std;
long long findTargetSumWays(const vector<int>& values, int target) {
    // Minus signs form a subset summing to (total-target)/2.
    long long total = accumulate(values.begin(), values.end(), 0LL);
    long long rest = total - target;
    // The desired target must produce a feasible integer subset sum.
    if (total < 0 || target > total || target < -total || rest % 2) return 0;
    int needed = (int)(rest / 2);
    vector<long long> ways(needed + 1, 0);
    ways[0] = 1;
    for (int value : values) {
        // This subset transformation assumes nonnegative values.
        if (value < 0) return 0;
        for (int sum = needed; sum >= value; --sum)
            ways[sum] += ways[sum - value];
    }
    return ways[needed];
}

s16-coin-change-2-dp-22.code:
// Approach: Process coin types outside and amounts forward; this counts combinations without order.
#include <vector>
using namespace std;
long long change(int amount, const vector<int>& coins) {
    // A negative amount has no coin combinations.
    if (amount < 0) return 0;
    vector<long long> ways(amount + 1, 0);
    ways[0] = 1;
    // Process one coin type at a time so different orders are not double-counted.
    for (int coin : coins) {
        // Zero or negative coin denominations cannot be processed in this recurrence.
        if (coin <= 0) continue;
        for (int sum = coin; sum <= amount; ++sum)
            // Extend every existing combination for the smaller amount with this coin.
            ways[sum] += ways[sum - coin];
    }
    return ways[amount];
}

s16-unbounded-knapsack-dp-23.code:
// Approach: Update capacities upward for each item, permitting repeated selection of that item.
#include <algorithm>
#include <vector>
using namespace std;
long long unboundedKnapsack(int capacity, const vector<int>& weight,
                            const vector<int>& value) {
    // Capacity and item arrays must describe a valid instance.
    if (capacity < 0 || weight.size() != value.size()) return 0;
    vector<long long> dp(capacity + 1, 0);
    for (int i = 0; i < (int)weight.size(); ++i) {
        // A nonpositive weight would make unlimited reuse ill-defined.
        if (weight[i] <= 0) continue;
        // Ascending capacities allow the same item to be used again.
        for (int cap = weight[i]; cap <= capacity; ++cap)
            // Either skip this item or take it and reuse the remaining capacity.
            dp[cap] = max(dp[cap], dp[cap - weight[i]] + value[i]);
    }
    return dp[capacity];
}

s16-rod-cutting-problem-dp-24.code:
// Approach: Treat each cut length as an item usable repeatedly; maximize revenue for the full rod.
#include <algorithm>
#include <vector>
using namespace std;
long long cutRod(const vector<int>& price) {
    int n = (int)price.size();
    vector<long long> dp(n + 1, 0);
    // A cut length can be reused, just like an unbounded knapsack item.
    for (int length = 1; length <= n; ++length)
        for (int rod = length; rod <= n; ++rod)
            // Compare keeping the current best with taking one cut of this length.
            dp[rod] = max(dp[rod], dp[rod - length] + price[length - 1]);
    return dp[n];
}

