// Approach: Update capacities downward, so no item is chosen more than once.
#include <algorithm>
#include <vector>
using namespace std;
long long zeroOneKnapsack(int capacity, const vector<int>& weight,
                          const vector<int>& value) {
    // Capacity and item arrays must describe a valid instance.
    if (capacity < 0 || weight.size() != value.size()) return 0;
    vector<long long> dp(capacity + 1, 0);
    for (int i = 0; i < (int)weight.size(); ++i) {
        // This implementation accepts only nonnegative item weights.
        if (weight[i] < 0) return 0;
        // Descending capacities stop the same item being reused.
        for (int cap = capacity; cap >= weight[i]; --cap)
            // This item's value is added to a capacity computed before using it.
            dp[cap] = max(dp[cap], dp[cap - weight[i]] + value[i]);
    }
    return dp[capacity];
}

s16-longest-common-subsequence-dp-25.code:
// Approach: When characters match, extend a shorter LCS; otherwise keep the better result after
//   skipping one character.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
int longestCommonSubsequence(const string& a, const string& b) {
    // A match extends the diagonal LCS; otherwise keep the better neighbor.
    vector<int> previous(b.size() + 1, 0), current(b.size() + 1, 0);
    for (char x : a) {
        fill(current.begin(), current.end(), 0);
        for (int j = 1; j <= (int)b.size(); ++j) {
            // Equal current letters extend the LCS of shorter prefixes.
            if (x == b[j - 1]) {
                // Matching letters extend the LCS of the two shorter prefixes.
                current[j] = 1 + previous[j - 1];
            } else {
                // Skip one letter from either string and keep the better result.
                current[j] = max(previous[j], current[j - 1]);
            }
        }
        previous.swap(current);
    }
    return previous.back();
}

