// Approach: Build the LCS length table, then backtrack from its bottom-right corner to recover one
//   subsequence.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
string printLCS(const string& a, const string& b) {
    // LCS lengths let us backtrack an actual sequence.
    int n = (int)a.size(), m = (int)b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            // Equal letters appear in the reconstructed common subsequence.
            if (a[i - 1] == b[j - 1]) {
                // A common letter extends the answer for shorter prefixes.
                dp[i][j] = 1 + dp[i - 1][j - 1];
            } else {
                // Skip one final letter and keep the longer option.
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    string result;
    for (int i = n, j = m; i > 0 && j > 0;) {
        // Matching characters belong to this LCS and move both indices back.
        if (a[i - 1] == b[j - 1]) {
            result.push_back(a[i - 1]);
            --i; --j;
        // When letters differ, follow the table cell that retained the longer LCS.
        } else if (dp[i - 1][j] >= dp[i][j - 1]) {
            // The upper cell kept the answer, so skip a's last letter.
            --i;
        } else {
            // The left cell kept the answer, so skip b's last letter.
            --j;
        }
