    // Compare s with its reverse using the usual LCS recurrence.
    for (char x : s) {
        fill(current.begin(), current.end(), 0);
        for (int j = 1; j <= (int)s.size(); ++j) {
            // Equal letters extend the common subsequence with the reversed string.
            if (x == reversed[j - 1]) {
