// Approach: Backtrack through the LCS table, appending the unmatched character from whichever string
//   is skipped.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
string shortestCommonSupersequence(const string& a, const string& b) {
    // Follow the LCS table to combine strings without duplicating matches.
    int n = (int)a.size(), m = (int)b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            // A shared letter belongs once in the combined string.
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1; // one shared letter
            } else {
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    string result;
    int i = n, j = m;
    while (i > 0 && j > 0) {
        // Include a shared character once, then move back in both strings.
        if (a[i - 1] == b[j - 1]) {
            result.push_back(a[--i]); --j;
        // Otherwise follow the stronger LCS direction while adding a letter.
        } else if (dp[i - 1][j] >= dp[i][j - 1]) {
            // a's letter is not shared here, so append it separately.
            result.push_back(a[--i]);
        } else {
            // b's letter is not shared here, so append it separately.
            result.push_back(b[--j]);
        }
    }
    while (i > 0) result.push_back(a[--i]);
    while (j > 0) result.push_back(b[--j]);
    reverse(result.begin(), result.end());
    return result;
}

