long long numDistinct(const string& source, const string& target,
                      long long mod = 0) {
    vector<long long> ways(target.size() + 1, 0);
    ways[0] = 1;
    for (char ch : source)
        for (int j = (int)target.size(); j >= 1; --j)
            // A matching target character can extend every shorter matching subsequence.
            if (ch == target[j - 1]) {
                ways[j] += ways[j - 1];
