// Approach: At each pair of prefixes, either match equal characters or pay one for insert, delete, or
//   replace.
#include <algorithm>
#include <numeric>
#include <string>
#include <vector>
using namespace std;
int editDistance(const string& a, const string& b) {
    // Empty-to-prefix distance is the prefix length (all insertions).
    int m = (int)b.size();
    vector<int> previous(m + 1), current(m + 1);
    iota(previous.begin(), previous.end(), 0);
    for (int i = 1; i <= (int)a.size(); ++i) {
        current[0] = i;
        for (int j = 1; j <= m; ++j) {
            // Matching final letters cost no additional edit.
            if (a[i - 1] == b[j - 1]) {
                // Equal final letters need no new edit.
                current[j] = previous[j - 1];
            } else {
                // Delete from a, insert into a, or replace its last letter.
                int deletion = previous[j];
                int insertion = current[j - 1];
                int replacement = previous[j - 1];
                current[j] = 1 + min({deletion, insertion, replacement});
            }
        }
        previous.swap(current);
    }
    return previous[m];
}

