// Approach: A '?' consumes one character; a '*' consumes zero or more. Update pattern-prefix matches
//   for each text prefix.
#include <string>
#include <vector>
using namespace std;
bool wildcardMatch(const string& pattern, const string& text) {
    // Empty pattern matches empty text; only '*' can extend that match.
    int m = (int)text.size();
    vector<char> previous(m + 1, false), current(m + 1, false);
    previous[0] = true;
    for (char p : pattern) {
        current[0] = p == '*' && previous[0];
        for (int j = 1; j <= m; ++j) {
            // A star has two choices: match nothing or consume another character.
            if (p == '*') {
                // '*' matches empty text (above) or one more character (left).
                current[j] = previous[j] || current[j - 1];
            // A question mark or matching literal consumes exactly one character.
            } else if (p == '?' || p == text[j - 1]) {
                // '?' or an equal literal consumes exactly one character.
                current[j] = previous[j - 1];
            } else {
                current[j] = false; // literal mismatch
            }
        }
        previous.swap(current);
        fill(current.begin(), current.end(), false);
    }
    return previous[m];
}

