// Approach: Choose the final split between matrices i and j, adding optimal costs of both sides and
//   their multiplication.
#include <algorithm>
#include <climits>
#include <vector>
using namespace std;
long long chainMemo(int i, int j, const vector<int>& dims,
                    vector<vector<long long>>& memo) {
    // Save interval costs to avoid solving the same chain again.
    // One matrix needs no multiplication.
    if (i == j) return 0;
    long long& answer = memo[i][j];
    // A cached interval cost avoids repeating the same split search.
    if (answer != -1) return answer;
    answer = LLONG_MAX / 4;
    for (int split = i; split < j; ++split)
        answer = min(answer, chainMemo(i, split, dims, memo)
                    + chainMemo(split + 1, j, dims, memo)
                    + 1LL * dims[i - 1] * dims[split] * dims[j]);
    return answer;
}
long long matrixChainMemo(const vector<int>& dims) {
    int n = (int)dims.size() - 1;
    // No matrices means zero multiplication cost.
    if (n <= 0) return 0;
    vector<vector<long long>> memo(n + 1, vector<long long>(n + 1, -1));
    return chainMemo(1, n, dims, memo);
}

