    vector<vector<long long>> dp(n + 2, vector<long long>(n + 2, 0));
    // Smaller cut intervals must be solved before larger ones.
    for (int width = 1; width <= n; ++width)
        for (int i = 1; i + width - 1 <= n; ++i) {
