// Approach: Choose which balloon bursts last in each interval; then its two neighbors are the fixed
//   interval boundaries.
#include <algorithm>
#include <vector>
using namespace std;
long long maxCoinsBurstBalloons(const vector<int>& balloons) {
    // Boundary 1s let every balloon use the same recurrence.
    vector<int> value;
    value.push_back(1);
    value.insert(value.end(), balloons.begin(), balloons.end());
    value.push_back(1);
    int n = (int)balloons.size();
    vector<vector<long long>> dp(n + 2, vector<long long>(n + 2, 0));
    // Shorter intervals must be solved before intervals that contain them.
    for (int width = 1; width <= n; ++width)
        for (int left = 1; left + width - 1 <= n; ++left) {
            int right = left + width - 1;
            // Neighbors outside [left,right] remain when its last balloon bursts.
            for (int last = left; last <= right; ++last)
                // Treat each candidate as the last balloon popped in this interval.
                dp[left][right] = max(dp[left][right],
                    dp[left][last - 1] + dp[last + 1][right]
                    + 1LL * value[left - 1] * value[last] * value[right + 1]);
        }
    return dp[1][n];
}

s16-evaluate-boolean-expression-to-true-.code:
// Approach: For each operator, combine counts of true and false expressions on both sides according
//   to its truth table.
#include <string>
#include <vector>
using namespace std;
int countTrueParenthesizations(const string& expression) {
    const long long MOD = 1000000007;
    int n = ((int)expression.size() + 1) / 2;
    // An empty expression has no true parenthesizations.
    if (expression.empty()) return 0;
    vector<vector<long long>> yes(n, vector<long long>(n, 0));
    vector<vector<long long>> no(n, vector<long long>(n, 0));
    for (int i = 0; i < n; ++i) {
        yes[i][i] = expression[2 * i] == 'T';
        no[i][i] = expression[2 * i] == 'F';
    }
    for (int width = 2; width <= n; ++width)
        for (int left = 0; left + width <= n; ++left) {
            int right = left + width - 1;
            // Try every operator as the last operation for this interval.
            for (int split = left; split < right; ++split) {
                long long lt = yes[left][split], lf = no[left][split];
                long long rt = yes[split + 1][right], rf = no[split + 1][right];
                char op = expression[2 * split + 1];
                // For AND, true requires both sides true.
                if (op == '&') {
                    yes[left][right] += lt * rt;
                    no[left][right] += lt * rf + lf * rt + lf * rf;
                // For OR, false requires both sides false; remaining pairs are true.
                } else if (op == '|') {
                    yes[left][right] += lt * rt + lt * rf + lf * rt;
                    no[left][right] += lf * rf;
                } else { // XOR
                    yes[left][right] += lt * rf + lf * rt;
                    no[left][right] += lt * rt + lf * rf;
                }
                yes[left][right] %= MOD;
                no[left][right] %= MOD;
            }
        }
    return (int)yes[0][n - 1];
}

s16-palindrome-partitioning-ii-dp-53.code:
// Approach: Precompute palindromic substrings; from each starting index, choose the next palindrome
//   minimizing remaining cuts.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
int minPalindromeCuts(const string& s) {
    // Precompute palindromic intervals before minimizing cuts.
    int n = (int)s.size();
    // An empty string needs no cuts.
    if (!n) return 0;
    vector<vector<char>> palindrome(n, vector<char>(n, false));
    for (int length = 1; length <= n; ++length)
        for (int i = 0; i + length <= n; ++i) {
            int j = i + length - 1;
            palindrome[i][j] = s[i] == s[j]
                && (length <= 2 || palindrome[i + 1][j - 1]);
        }
    vector<int> parts(n + 1, n + 1);
    parts[n] = 0;
    for (int i = n - 1; i >= 0; --i)
        for (int j = i; j < n; ++j)
            // A palindromic interval can form one final partition piece.
            if (palindrome[i][j]) parts[i] = min(parts[i], 1 + parts[j + 1]);
    return parts[0] - 1;
}

s16-partition-array-for-maximum-sum-dp-5.code:
// Approach: For each prefix, try the final block of up to k items; its contribution is block length
//   times block maximum.
#include <algorithm>
#include <vector>
using namespace std;
long long maxSumAfterPartitioning(const vector<int>& values, int k) {
    // dp[i] is the best score for the first i elements.
    int n = (int)values.size();
    vector<long long> dp(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        int maximum = 0;
        for (int length = 1; length <= k && length <= i; ++length) {
            // Extend the final block backward and update its maximum.
            maximum = max(maximum, values[i - length]);
            // Try every allowed final partition ending at i.
            dp[i] = max(dp[i], dp[i - length] + 1LL * length * maximum);
        }
    }
    return dp[n];
}

